    operation: tokio::sync::OwnedMutexGuard<()>,
}

fn json_nodes(value: &Value) -> usize {
    match value {
        Value::Object(object) => 1 + object.values().map(json_nodes).sum::<usize>(),
        Value::Array(items) => 1 + items.iter().map(json_nodes).sum::<usize>(),
        _ => 1,
    }
}

