      <p>Discovered from this caller's mounted filesystem. {methods.length} methods.</p>
    </div>
    {#if surface}<button type="button" disabled={loading || pending} onclick={() => void refresh()}>
      {loading ? "Discovering…" : "Refresh methods"}</button>{/if}
