+/// Topic carrying a response tool-use ack. `<owner-key>` is the
+/// chat_response projection owner key (`sha256(principal_id)`), the same
+/// identity the committed signal announces.
+pub(crate) fn tool_ack_topic(owner_key_hex: &str) -> String {
+    format!("{}{owner_key_hex}", op_plugins::state_plugins::emqx::TOOL_ACK_PREFIX)
+}
+
+/// Parsed tool-use ack receipt from an ack publish payload.
+#[derive(Debug, Clone, PartialEq, Eq)]
+pub(crate) struct ToolUseAck {
+    pub owner_key: String,
+    pub turn_id: String,
+    pub turn_hash: String,
+}
+
+/// Parses a tool-use ack publish payload. The payload is the serialized
+/// `ResponseCommittedSignal` receipt fields only; anything else is refused.
+pub(crate) fn parse_tool_use_ack(payload: &[u8]) -> Result<ToolUseAck, String> {
+    #[derive(serde::Deserialize)]
+    struct Wire {
+        owner_key: String,
+        turn_id: String,
+        turn_hash: String,
+    }
+    let wire: Wire = serde_json::from_slice(payload)
+        .map_err(|error| format!("tool-use ack payload does not match its receipt shape: {error}"))?;
+    if !op_plugins::state_plugins::emqx::valid_owner_key(&wire.owner_key)
+        && wire.owner_key.len() != 64
+    {
+        return Err("tool-use ack owner key is not 64 hex characters".into());
+    }
+    Ok(ToolUseAck {
+        owner_key: wire.owner_key,
+        turn_id: wire.turn_id,
+        turn_hash: wire.turn_hash,
+    })
+}
+
+/// Verifies a published tool-use ack against the durable committed turn:
+/// the turn must exist in some principal's private scope with exactly this
+/// turn_id and turn_hash. Content-free: the probe never reads turn_json.
+/// `false` is the hallucination signal.
+pub(crate) async fn verify_tool_use_ack(
+    engine: &MutationEngine,
+    ack: &ToolUseAck,
+) -> anyhow::Result<bool> {
+    let store = engine.chat_response_cozo().await?;
+    let (turn_id, turn_hash) = (ack.turn_id.clone(), ack.turn_hash.clone());
+    tokio::task::spawn_blocking(move || store.chat_turn_receipt_exists(&turn_id, &turn_hash))
+        .await
+        .map_err(|error| anyhow::anyhow!("tool-use ack verify worker failed: {error}"))?
+        .map_err(|error| anyhow::anyhow!("tool-use ack probe failed: {error}"))
+}
+
