    &mut self,
    request: &Request<'_>,
    ino: u64,
    fh: u64,
    _flags: i32,
    _lock_owner: Option<u64>,
    _flush: bool,
    reply: ReplyEmpty,
) {
    self.submit(ino, fh, request.uid(), PendingReply::Fuse(reply), true);
}
